        request_id,
        admin_id,
        action,
        campaign_id,
        payload_hash,
        response_json
    ) VALUES (
        p_request_id,
        v_admin_id,
        'send_now',
        v_camp.id,
        v_payload_hash,
        v_response
    );

    RETURN v_response;
END;
$$;

