ateTimeCursor(time, \"warning1\"),\n61:             ) else AdminMemberWarningsEnvelope(items = listOf(AdminMemberWarningItem(\"warning2\", target, message = \"two\", createdAt = time)))\n62:     }\n63: \n64:     @Test fun concurrentCreditAndWarningPaginationDoesNotDiscardCreditPageOrLeaveSpinner() = runBlocking {\n65:         val dispatcher = StandardTestDispatcher()\n66:         Dispatchers.setMain(dispatcher)\n67:         val app: Application = RuntimeEnvironment.getApplication()\n68:         SessionCacheManager.clear(app)\n69:         val store = ViewModelStore()\n70:         val client = createSupabaseClient(\"https://fixture.invalid\", \"dummy\") {\n71:             install(Auth) {\n72:                 sessionManager = MemorySessionManager()\n73:                 codeVerifierCache = MemoryCodeVerifierCache()\n74:                 autoLoadFromStorage = false\n75:                 autoSaveToStorage = false\n76:                 enableLifecycleCallbacks = false\n77:             }\n78:             install(Postgrest)\n79:             httpEngine = MockEngine { respond(\"{}\", headers = headersOf(HttpHeaders.ContentType, \"application/json\")) }\n80:         }\n81:         try {\n82:             client.auth.importSession(Json { ignoreUnknownKeys = true }.decodeFromString<UserSession>(\n83:                 \"\"\"{\"access_token\":\"fixture-token\",\"refresh_token\":\"fixture-ref\",\"expires_in\":3600,\"token_type\":\"bearer\",\"user\":{\"id\":\"$admin\",\"aud\":\"authenticated\"}}\"\"\"\n84:             ))\n85:             val repository = FixtureRepository(client)\n86:             val vm = MemberDetailViewModel(target, repository, AuthRepository(client, app), Localizer(app))\n87:             store.put(\"member\", vm)\n88:             dispatcher.scheduler.advanceUntilIdle()\n89:             assertFalse(vm.uiState.value.isLoading)\n90:             assertTrue(vm.uiState.value.creditHasMore)\n91:             assertTrue(vm.uiState.value.warningsHasMore)\n92: \n93:             vm.loadMoreCreditHistory()\n94:             dispatcher.scheduler.runCurrent()\n95:             assertTrue(repository.creditPageStarted)\n96:             assertTrue(vm.uiState.value.isCreditsLoading)\n97:             vm.loadMoreWarnings()\n98:             dispatcher.scheduler.advanceUntilIdle()\n99:             repository.creditGate.complete(Unit)\n100:             dispatcher.scheduler.advanceUntilIdle()\n101: \n102:             assertFalse(\"Starting warning pagination must not strand the credit spinner\", vm.uiState.value.isCreditsLoading)\n103:             assertEquals(listOf(\"credit1\", \"credit2\"), vm.uiState.value.creditHistory.map { it.id })\n104:             assertEquals(listOf(\"warning1\", \"warning2\"), vm.uiState.value.warnings.map { it.id })\n105:         } finally {\n106:             store.clear()\n107:             client.close()\n108:             SessionCacheManager.clear(app)\n109:             Dispatchers.resetMain()\n110:         }\n111:     }\n112: }\n\n(End of file - total 112 lines)\n</content>","metadata":{"preview":"package com.ntt.crosstest.audit\n\nimport android.app.Application\nimport androidx.lifecycle.ViewModelStore\nimport com.ntt.crosstest.data.*\nimport com.ntt.crosstest.ui.viewmodels.MemberDetailViewModel\nimport io.github.jan.supabase.SupabaseClient\nimport io.github.jan.supabase.auth.Auth\nimport io.github.jan.supabase.auth.MemoryCodeVerifierCache\nimport io.github.jan.supabase.auth.MemorySessionManager\nimport io.github.jan.supabase.auth.auth\nimport io.github.jan.supabase.auth.user.UserSession\nimport io.github.jan.supabase.createSupabaseClient\nimport io.github.jan.supabase.postgrest.Postgrest\nimport io.ktor.client.engine.mock.MockEngine\nimport io.ktor.client.engine.mock.respond\nimport io.ktor.http.HttpHeaders\nimport io.ktor.http.headersOf\nimport kotlinx.coroutines.CompletableDeferred\nimport kotlinx.coroutines.Dispatchers","truncated":false,"loaded":[],"display":{"type":"file","path":"F:\\AI\\12Tester\\audit\\admin-expansio