+{"type":"tool_use","timestamp":1793531108585,"sessionID":"ses_e6937dd3effeGOX6UypJnYdiYq","part":{"type":"tool","tool":"read","callID":"FzLP8tbtCYHgUGYb","state":{"status":"completed","input":{"filePath":"F:\\AI\\12Tester\\audit\\admin-expansion-2026-11-01\\business-stage\\071_business_policies.sql","limit":200,"offset":850},"output":"<path>F:\\AI\\12Tester\\audit\\admin-expansion-2026-11-01\\business-stage\\071_business_policies.sql</path>\n<type>file</type>\n<content>\n850: AS $$\n851: declare\n852:     v_date date := coalesce(p_date, (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date);\n853:     v_policy public.business_policies;\n854: begin\n855:     if not isfinite(v_date) then\n856:         raise exception 'BUSINESS_POLICY_INVALID_DATE';\n857:     end if;\n858: \n859:     select p.* into v_policy\n860:     from public.business_policies p\n861:     where p.effective_from <= v_date\n862:     order by p.effective_from desc\n863:     limit 1;\n864: \n865:     if v_policy.id is null then\n866:         raise exception 'BUSINESS_POLICY_NOT_FOUND';\n867:     end if;\n868: \n869:     return v_policy;\n870: end;\n871: $$;\n872: \n873: CREATE OR REPLACE FUNCTION public.get_effective_business_policy(p_date date DEFAULT NULL::date)\n874: RETURNS jsonb\n875: LANGUAGE plpgsql\n876: STABLE SECURITY DEFINER\n877: SET search_path TO ''\n878: AS $$\n879: declare\n880:     v_policy public.business_policies;\n881: begin\n882:     v_policy := public._get_effective_business_policy_row(p_date);\n883:     return public._format_business_policy_json(v_policy);\n884: end;\n885: $$;\n886: \n887: CREATE OR REPLACE FUNCTION public.get_business_quote(\n888:     p_quote_type text,\n889:     p_params jsonb DEFAULT '{}'::jsonb\n890: )\n891: RETURNS jsonb\n892: LANGUAGE plpgsql\n893: STABLE SECURITY DEFINER\n894: SET search_path TO ''\n895: AS $$\n896: declare\n897:     v_uid uuid := auth.uid();\n898:     v_policy public.business_policies;\n899:     v_rev text;\n900:     v_type text := lower(btrim(coalesce(p_quote_type, '')));\n901:     v_slot integer;\n902:     v_slot_cost integer;\n903: begin\n904:     if v_uid is null then\n905:         raise exception 'NOT_AUTHENTICATED';\n906:     end if;\n907: \n908:     v_policy := public._get_effective_business_policy_row();\n909:     v_rev := public._get_business_policy_revision();\n910: \n911:     if v_type = 'push' then\n912:         return jsonb_build_object(\n913:             'quote_type', 'push',\n914:             'cost', v_policy.push_fee,\n915:             'revision', v_rev\n916:         );\n917:     elsif v_type = 'slot' then\n918:         v_slot := coalesce((p_params ->> 'slot_number')::integer, 2);\n919:         if v_slot < 2 or v_slot > 6 then\n920:             raise exception 'INVALID_SLOT_NUMBER';\n921:         end if;\n922:         v_slot_cost := case\n923:             when v_slot = 2 then v_policy.slot_fee_2\n924:             when v_slot = 3 then v_policy.slot_fee_3\n925:             else v_policy.slot_fee_4_plus\n926:         end;\n927:         return jsonb_build_object(\n928:             'quote_type', 'slot',\n929:             'slot_number', v_slot,\n930:             'cost', v_slot_cost,\n931:             'renewal_days', v_policy.slot_renewal_days,\n932:             'revision', v_rev\n933:         );\n934:     elsif v_type = 'app_update' then\n935:         return jsonb_build_object(\n936:             'quote_type', 'app_update',\n937:             'reward_per_claim', v_policy.app_update_reward_per_claim,\n938:             'max_claims', v_policy.app_update_max_claims,\n939:             'reserved_budget', v_policy.app_update_reward_per_claim * v_policy.app_update_max_claims,\n940:             'revision', v_rev\n941:         );\n942:     elsif v_type = 'all' then\n943:         return jsonb_build_object(\n944:             'quote_type', 'all',\n945:             'revision', v_rev,\n946:             'push_fee', v_policy.push_fee,\n947:             'slot_fees', jsonb_build_object(\n948:                 'slot_2', v_policy.slot_fee_2,\n949:                 'slot_3', v_policy.slot_fee_3,\n950:                 'slot_4_plus', v_policy.slot_fee_4_plus,\n951:                 'renewal_days', v_policy.slot_renewal_days\n952:             ),\n953:             'app_update_rewards', jsonb_build_object(\n954:                 'reward_per_claim', v_policy.app_update_reward_per_claim,\n955:                 'max_claims', v_policy.app_update_max_claims,\n956:                 'reserved_budget', v_policy.app_update_reward_per_claim * v_policy.app_update_max_claims\n957:             ),\n958:             'report_rewards', jsonb_build_object(\n959:                 'provisional_reward', v_policy.report_provisional_reward,\n960:                 'review_tester_bonus', v_policy.report_review_tester_bonus,\n961:                 'review_owner_bonus', v_policy.report_review_owner_bonus\n962:             )\n963:         );\n964:     else\n965:         raise exception 'INVALID_QUOTE_TYPE: Must be push, slot, app_update, or all';\n966:     end if;\n967: end;\n968: $$;\n969: \n970: -- ============================================================================\n971: -- 6. SECURITY: RLS & MINIMAL GRANTS\n972: -- ============================================================================\n973: \n974: ALTER TABLE public.business_policies ENABLE ROW LEVEL SECURITY;\n975: ALTER TABLE public.business_policies NO FORCE ROW LEVEL SECURITY;\n976: \n977: ALTER TABLE public.business_policy_changes ENABLE ROW LEVEL SECURITY;\n978: ALTER TABLE public.business_policy_changes NO FORCE ROW LEVEL SECURITY;\n979: \n980: ALTER TABLE public.slot_purchase_receipts ENABLE ROW LEVEL SECURITY;\n981: ALTER TABLE public.slot_purchase_receipts NO FORCE ROW LEVEL SECURITY;\n982: \n983: DROP POLICY IF EXISTS \"business_policies_select_all\" ON public.business_policies;\n984: CREATE POLICY \"business_policies_select_all\" ON public.business_policies\n985:     FOR SELECT TO authenticated USING (true);\n986: \n987: DROP POLI