1240: -- Tester reports queue with joined display data
1241: CREATE OR REPLACE FUNCTION public.admin_get_tester_reports_queue(
1242:     p_status text DEFAULT 'pending'::text,
1243:     p_campaign_id uuid DEFAULT NULL::uuid,
1244:     p_tester_id uuid DEFAULT NULL::uuid,
1245:     p_owner_id uuid DEFAULT NULL::uuid,
1246:     p_submission_context text DEFAULT NULL::text,
1247:     p_limit integer DEFAULT 50,
1248:     p_cursor_created_at timestamptz DEFAULT NULL::timestamptz,
1249:     p_cursor_id uuid DEFAULT NULL::uuid
1250: )
1251: RETURNS jsonb
1252: LANGUAGE plpgsql
1253: SECURITY DEFINER
1254: SET search_path TO 'public'
1255: AS $function$
1256: declare
1257:     v_caller_id uuid;
1258:     v_limit int;
1259:     v_rows jsonb;
1260:     v_has_more boolean := false;
1261:     v_next_cursor jsonb := null;
1262:     v_count int;
1263: begin
1264:     v_caller_id := public.assert_unlocked_admin();
1265:     v_limit := greatest(1, least(coalesce(p_limit, 50), 100));
1266: 
1267:     with raw_reports as (
1268:         select
1269:             tr.id,
1270:             tr.campaign_id,
1271:             c.app_name as campaign_name,
1272:             c.package_name,
1273:             c.owner_id,
1274:             po.display_name as owner_name,
1275:             tr.user_id as tester_id,
1276:             pt.display_name as tester_name,
1277:             pt.email as tester_email,
1278:             tr.report_type,
